#define main legacy_main
#include "silu-cuda/main.cu"
#undef main
#include <vector>
int main(){int n=4096,repeat=10;std::vector<float>x(n),d(n),out(n),want(n),values;for(int i=0;i<n;i++){x[i]=float(i%257-128)/32.f;d[i]=float(i%31-15)/16.f;}float *dx,*dd,*dy;cudaMalloc(&dx,n*4);cudaMalloc(&dd,n*4);cudaMalloc(&dy,n*4);cudaMemcpy(dx,x.data(),n*4,cudaMemcpyHostToDevice);cudaMemcpy(dd,d.data(),n*4,cudaMemcpyHostToDevice);
auto run=[&](int m){switch(m){case 0:silu_forward(dx,dy,n,256);break;case 1:silu_forward2(dx,dy,n,256);break;case 2:silu_backward(dd,dx,dy,n,256);break;case 3:silu_backward2(dd,dx,dy,n,256);break;case 4:silu_backward3(dd,dx,dy,n,256);break;}};for(int m=0;m<5;m++)run(m);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;
for(int trial=1;trial<=5;trial++){values.clear();double total=0.,err=0.,times[5];bool correct=true;for(int m=0;m<5;m++){cudaMemset(dy,0,n*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)run(m);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;times[m]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;total+=times[m];cudaMemcpy(out.data(),dy,n*4,cudaMemcpyDeviceToHost);if(m<2)silu_forward_reference(x.data(),want.data(),n);else silu_backward_reference(d.data(),x.data(),want.data(),n);for(int i=0;i<n;i++){err=fmax(err,fabs(double(out[i])-want[i]));correct &=std::isfinite(out[i])&&fabs(out[i]-want[i])<=1e-4f;}values.insert(values.end(),out.begin(),out.end());}char file[32];snprintf(file,sizeof(file),"trial_%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(values.data(),4,values.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.14g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.14g,\"timing_region\":\"sum_five_synchronized_kernel_loop_means\",\"jit_excluded\":true,\"internal_repeats\":%d,\"subkernel_times_seconds\":[%.14g,%.14g,%.14g,%.14g,%.14g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,total,correct?"true":"false",5*n,err,repeat,times[0],times[1],times[2],times[3],times[4],file,5*n);if(!correct)return 1;}cudaFree(dx);cudaFree(dd);cudaFree(dy);}
